<section class="card"><div class="card-head"><div><h2>Recent Feedback</h2></div><a class="btn secondary small" href="<?= e(app_url('admin/feedback.php')) ?>">View all</a></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Office</th><th>Service</th><th>Sentiment</th><th>Review</th><th>Final</th><th>Comment</th></tr></thead><tbody><?php foreach($recent as $row):?><tr><td><?= e(date('M d, Y',strtotime($row['visit_date']))) ?></td><td><?= e($row['office_code']) ?></td><td><?= e($row['service_received']) ?></td><td><?= badge(status_label($row['sentiment']),$row['sentiment']) ?></td><td><?= e(status_label($row['review_status'])) ?></td><td><?= number_format((float)$row['final_score'],2) ?>%</td><td><?= e(mb_strimwidth($row['comment'],0,100,'…')) ?></td></tr><?php endforeach;?><?php if(!$recent):?><tr><td colspan="7" class="empty-state">No feedback yet.</td></tr><?php endif;?></tbody></table></div></section>
